export interface CrystalResponse {
  analysis: string;
  options: {
    type: string;
    text: string;
  }[];
  rhythm: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text?: string;
  image?: string;
  timestamp: number;
  data?: CrystalResponse;
}

export enum AnalysisMode {
  TEXT = 'TEXT',
  IMAGE = 'IMAGE'
}

import { GoogleGenAI, Type } from "@google/genai";
import { CRYSTAL_SYSTEM_PROMPT } from '../constants';
import { CrystalResponse } from '../types';

// Initialize Gemini
// Note: In a real production app, ensure strict backend proxying or secure env var usage.
// Here we follow the provided instructions to use process.env.API_KEY directly.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeInteraction = async (
  textInput: string,
  imageBase64?: string
): Promise<CrystalResponse> => {
  try {
    const parts: any[] = [];

    if (imageBase64) {
      // Clean base64 string if it contains metadata prefix
      const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg', // Assuming JPEG or PNG, generic safe fallback usually works or detect from header
          data: cleanBase64
        }
      });
    }

    if (textInput) {
      parts.push({
        text: textInput
      });
    }

    if (parts.length === 0) {
      throw new Error("No input provided");
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest', // Fast, good for multimodal
      contents: {
        role: 'user',
        parts: parts
      },
      config: {
        systemInstruction: CRYSTAL_SYSTEM_PROMPT,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            options: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  text: { type: Type.STRING }
                }
              }
            },
            rhythm: { type: Type.STRING }
          }
        }
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from Crystal Prime");

    return JSON.parse(resultText) as CrystalResponse;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { CrystalResponse } from '../types';
import { Copy, Terminal, Zap, Clock, Activity } from 'lucide-react';

interface TerminalOutputProps {
  data: CrystalResponse;
  loading: boolean;
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ data, loading }) => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const handleCopy = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  if (loading) {
    return (
      <div className="w-full border border-crystal-500/20 bg-surface/50 rounded-lg p-6 relative overflow-hidden h-64 flex flex-col items-center justify-center">
        <div className="absolute inset-0 bg-[linear-gradient(transparent_0%,rgba(20,184,166,0.1)_50%,transparent_100%)] animate-scan h-full w-full pointer-events-none" />
        <Activity className="text-crystal-400 w-12 h-12 animate-pulse mb-4" />
        <p className="font-mono text-crystal-300 animate-pulse text-sm tracking-widest">
          PROCESSANDO LEITURA HUMANA...
        </p>
      </div>
    );
  }

  if (!data) return null;

  return (
    <div className="w-full space-y-4 animate-[fadeIn_0.5s_ease-out]">
      {/* Analysis Section */}
      <div className="border border-crystal-500/30 bg-surface/80 rounded-lg p-4 backdrop-blur-sm">
        <div className="flex items-center gap-2 mb-2">
          <Terminal className="w-4 h-4 text-crystal-400" />
          <h3 className="font-mono text-xs text-crystal-400 uppercase tracking-widest">Leitura do Momento</h3>
        </div>
        <p className="font-sans text-lg text-white font-medium leading-relaxed">
          {data.analysis}
        </p>
      </div>

      {/* Responses Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {data.options.map((option, idx) => (
          <div 
            key={idx} 
            className="group relative border border-slate-700 bg-slate-900/50 hover:bg-slate-800/50 hover:border-crystal-500/50 rounded-lg p-4 transition-all duration-300 flex flex-col justify-between"
          >
            <div>
              <div className="flex items-center justify-between mb-3">
                <span className="font-mono text-[10px] uppercase tracking-wider text-slate-400 group-hover:text-crystal-300">
                  {option.type}
                </span>
                <Zap className="w-3 h-3 text-slate-600 group-hover:text-yellow-400 transition-colors" />
              </div>
              <p className="font-sans text-slate-200 text-lg mb-4">
                "{option.text}"
              </p>
            </div>

            <button
              onClick={() => handleCopy(option.text, idx)}
              className="w-full flex items-center justify-center gap-2 py-2 px-3 rounded bg-slate-800 hover:bg-crystal-600 hover:text-white text-slate-400 text-xs font-mono transition-all uppercase"
            >
              {copiedIndex === idx ? (
                <>Copiado</>
              ) : (
                <>
                  <Copy className="w-3 h-3" /> Copiar
                </>
              )}
            </button>
          </div>
        ))}
      </div>

      {/* Rhythm Section */}
      <div className="border border-indigo-500/20 bg-indigo-950/20 rounded-lg p-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Clock className="w-4 h-4 text-indigo-400" />
          <span className="font-mono text-xs text-indigo-300 uppercase tracking-widest">Ritmo Sugerido</span>
        </div>
        <span className="font-mono text-indigo-200 font-bold uppercase tracking-wider">
          {data.rhythm}
        </span>
      </div>
    </div>
  );
};

export default TerminalOutput;

