import { GoogleGenAI, Type } from "@google/genai";
import { CRYSTAL_SYSTEM_PROMPT, MODES } from '../constants';
import { CrystalResponse, AnalysisMode } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeInteraction = async (
  textInput: string,
  mode: AnalysisMode,
  flirtLevel: number,
  labiaLevel: number,
  imageBase64?: string
): Promise<CrystalResponse> => {
  try {
    const parts: any[] = [];

    // Find mode description
    const modeConfig = MODES.find(m => m.id === mode);
    const modeDesc = modeConfig ? `${modeConfig.label}: ${modeConfig.description}` : mode;

    // Construct the Contextual Prompt
    const promptText = `
CONFIGURAÇÃO ATUAL:
- MODO ATIVO: ${modeDesc}
- NÍVEL DE FLIRT (0-10): ${flirtLevel}
- NÍVEL DE LÁBIA (0-10): ${labiaLevel}

INPUT DO USUÁRIO:
${textInput || "(Apenas imagem fornecida)"}

TAREFA:
Analise o input (texto e/ou imagem) com base no Modo Ativo e nos Níveis definidos. Gere 3 opções de resposta e uma análise.
`;

    if (imageBase64) {
      const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    }

    parts.push({
      text: promptText
    });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest',
      contents: {
        role: 'user',
        parts: parts
      },
      config: {
        systemInstruction: CRYSTAL_SYSTEM_PROMPT,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            options: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  text: { type: Type.STRING }
                }
              }
            },
            rhythm: { type: Type.STRING }
          }
        }
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from Crystal Prime");

    return JSON.parse(resultText) as CrystalResponse;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

