import { GoogleGenAI, Type } from "@google/genai";
import { AMORIM_SYSTEM_PROMPT, MODES } from '../constants';
import { CrystalResponse, AnalysisMode } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeInteraction = async (
  textInput: string,
  mode: AnalysisMode,
  flirtLevel: number,
  labiaLevel: number,
  imageBase64?: string
): Promise<CrystalResponse> => {
  try {
    const parts: any[] = [];

    // Find mode description
    const modeConfig = MODES.find(m => m.id === mode);
    const modeDesc = modeConfig ? `${modeConfig.label}: ${modeConfig.description}` : mode;

    // Construct the Contextual Prompt with explicit multi-modal instructions
    const promptText = `
SYSTEM OS: AMORIM INC
---------------------
CONFIGURAÇÃO DE PERSONALIDADE:
- MODO ATIVO: ${modeDesc}
- NÍVEL DE FLIRT: ${flirtLevel}/10
- NÍVEL DE LÁBIA: ${labiaLevel}/10

INPUTS RECEBIDOS:
1. TEXTO DE APOIO/CONTEXTO: ${textInput ? `"${textInput}"` : "(Nenhum texto digitado)"}
2. IMAGEM ANEXADA: ${imageBase64 ? "SIM (Print de Story, DM ou Bio)" : "NÃO"}

INSTRUÇÃO DE PROCESSAMENTO (TEXTO + IMAGEM):
- Se houver AMBOS (Texto e Imagem): Considere o texto digitado como o contexto, a dúvida específica ou a intenção do usuário sobre a imagem anexada. Analise a imagem sob a ótica desse texto.
- Se houver APENAS IMAGEM: Faça a leitura completa dos elementos visuais, textos dentro da imagem (OCR implícito) e subtexto emocional.
- Se houver APENAS TEXTO: Analise a mensagem colada ou a situação descrita.

TAREFA FINAL:
Com base na combinação dos inputs, gere a "Leitura do Momento" e 3 opções de resposta magnéticas seguindo a identidade Amorim Inc.
`;

    if (imageBase64) {
      const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    }

    parts.push({
      text: promptText
    });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest',
      contents: {
        role: 'user',
        parts: parts
      },
      config: {
        systemInstruction: AMORIM_SYSTEM_PROMPT,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            options: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  text: { type: Type.STRING }
                }
              }
            },
            rhythm: { type: Type.STRING }
          }
        }
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return JSON.parse(resultText) as CrystalResponse;

  } catch (error) {
    console.error("Amorim Inc Error:", error);
    throw error;
  }
};

