import React, { useState } from 'react';
import { CrystalResponse } from '../types';
import { Copy, Terminal, Zap, Clock, Crown, Volume2, Loader } from 'lucide-react';
import { generateSpeech } from '../services/geminiService';

interface TerminalOutputProps {
  data: CrystalResponse;
  loading: boolean;
}

// Helper to decode Base64 string to Uint8Array
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper to decode raw PCM data into an AudioBuffer
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ data, loading }) => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [playingIndex, setPlayingIndex] = useState<number | null>(null);

  const handleCopy = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  const handlePlay = async (text: string, index: number) => {
    if (playingIndex !== null) return; // Prevent multiple plays

    try {
      setPlayingIndex(index);
      const base64Audio = await generateSpeech(text);

      if (base64Audio) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const pcmBytes = decode(base64Audio);
        const audioBuffer = await decodeAudioData(pcmBytes, audioContext, 24000, 1);

        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);

        source.onended = () => {
          setPlayingIndex(null);
          audioContext.close();
        };

        source.start(0);
      } else {
        setPlayingIndex(null);
      }
    } catch (error) {
      console.error("Audio playback failed", error);
      setPlayingIndex(null);
    }
  };

  if (loading) {
    return (
      <div className="w-full border border-gold-500/10 bg-obsidian-light/50 rounded-lg p-6 relative overflow-hidden h-64 flex flex-col items-center justify-center">
        <div className="absolute inset-0 bg-[linear-gradient(transparent_0%,rgba(201,162,77,0.05)_50%,transparent_100%)] animate-scan h-full w-full pointer-events-none" />
        <div className="relative z-10 flex flex-col items-center">
            <Crown className="text-gold-500 w-10 h-10 animate-pulse mb-4 opacity-80" />
            <p className="font-mono text-gold-400 animate-pulse text-xs tracking-[0.2em] uppercase">
            Processando Amorim Inc...
            </p>
            <p className="text-[9px] text-slate-600 mt-2 font-mono uppercase tracking-widest animate-pulse">
              Gemini 3 Thinking Mode Active
            </p>
        </div>
      </div>
    );
  }

  if (!data) return null;

  return (
    <div className="w-full space-y-4 animate-[fadeIn_0.5s_ease-out]">
      {/* Analysis Section */}
      <div className="border-l-2 border-gold-500 bg-obsidian-light/80 rounded-r-lg p-5 shadow-lg backdrop-blur-sm">
        <div className="flex items-center gap-2 mb-3">
          <Terminal className="w-3 h-3 text-gold-500" />
          <h3 className="font-mono text-[10px] text-gold-500 uppercase tracking-widest">Leitura do Momento</h3>
        </div>
        <p className="font-sans text-lg text-slate-200 font-medium leading-relaxed">
          {data.analysis}
        </p>
      </div>

      {/* Responses Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {data.options.map((option, idx) => (
          <div 
            key={idx} 
            className="group relative border border-white/5 bg-obsidian-lighter hover:border-gold-500/30 rounded-lg p-5 transition-all duration-500 flex flex-col justify-between hover:shadow-[0_0_20px_rgba(201,162,77,0.05)]"
          >
            <div>
              <div className="flex items-center justify-between mb-4">
                <span className="font-mono text-[9px] uppercase tracking-wider text-slate-500 group-hover:text-gold-400 transition-colors">
                  {option.type}
                </span>
                <Zap className="w-3 h-3 text-slate-700 group-hover:text-gold-500 transition-colors" />
              </div>
              <p className="font-sans text-slate-300 text-sm md:text-base leading-relaxed mb-6 group-hover:text-white transition-colors">
                "{option.text}"
              </p>
            </div>

            <div className="flex items-center gap-2">
              {/* Copy Button */}
              <button
                onClick={() => handleCopy(option.text, idx)}
                className="flex-1 flex items-center justify-center gap-2 py-2 px-3 rounded bg-black border border-white/5 hover:border-gold-500 hover:text-gold-400 text-slate-500 text-[10px] font-mono transition-all uppercase tracking-wider"
              >
                {copiedIndex === idx ? (
                  <>Copiado</>
                ) : (
                  <>
                    <Copy className="w-3 h-3" /> Copiar
                  </>
                )}
              </button>

              {/* Play Button */}
              <button
                onClick={() => handlePlay(option.text, idx)}
                disabled={playingIndex !== null}
                className={`flex items-center justify-center py-2 px-3 rounded border border-white/5 transition-all text-[10px]
                  ${playingIndex === idx 
                    ? 'bg-gold-500/20 text-gold-400 border-gold-500/30 animate-pulse' 
                    : 'bg-black text-slate-500 hover:text-gold-400 hover:border-gold-500'
                  }
                  ${playingIndex !== null && playingIndex !== idx ? 'opacity-30 cursor-not-allowed' : ''}
                `}
              >
                {playingIndex === idx ? (
                  <Loader className="w-3 h-3 animate-spin" />
                ) : (
                  <Volume2 className="w-3 h-3" />
                )}
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Rhythm Section */}
      <div className="border border-white/5 bg-obsidian-lighter rounded-lg p-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Clock className="w-3 h-3 text-gold-600" />
          <span className="font-mono text-[10px] text-slate-500 uppercase tracking-widest">Timing Sugerido</span>
        </div>
        <span className="font-mono text-gold-400 font-bold uppercase tracking-wider text-xs">
          {data.rhythm}
        </span>
      </div>
    </div>
  );
};

export default TerminalOutput;
